     * EXPLOIT MECHANISM:
     * The multiplication is performed using 32-bit signed integers.
     * If min_pu_size or ctb_count are crafted to be large enough,
     * the product exceeds INT32_MAX and wraps around to a small positive value.
     * The cast to size_t happens AFTER the overflow, so the allocator receives
     * the truncated/wrapped value instead of the true required size.
     */
    size_t mv_alloc_size = (size_t)(min_pu_size * sizeof(MvField));
    size_t ref_alloc_size = (size_t)(ctb_count * sizeof(RefPicListTab));

    printf("[INFO] Crafted inputs: min_pu_size=%d, ctb_count=%d\n", min_pu_size, ctb_count);
    printf("[INFO] Calculated allocation sizes (overflowed): mv=%zu, ref=%zu\n", mv_alloc_size, ref_alloc_size);

    /* Allocate based on the undersized, overflowed calculation */
    MvField *mv_pool = malloc(mv_alloc_size);
    RefPicListTab *ref_pool = malloc(ref_alloc_size);

    if (!mv_pool || !ref_pool) {
        printf("[INFO] Allocation failed or returned NULL\n");
        return;
    }

    /* 
     * SUBSEQUENT LOGIC ASSUMPTION:
     * The decoder later assumes the pool can hold min_pu_size MvFields
     * and ctb_count RefPicListTabs. Writing to these indices will
     * exceed the actual allocated memory, causing a heap buffer overflow.
     * 
     * Example (conceptual, not executed to prevent crash):
     * mv_pool[min_pu_size - 1] = (MvField){0, 0}; // Out-of-bounds write!
     * ref_pool[ctb_count - 1] = (RefPicListTab){0}; // Out-of-bounds write!
     */
    printf("[INFO] Decoder expects capacity for %d MvFields and %d RefPicListTabs\n", min_pu_size, ctb_count);
    printf("[INFO] Actual capacity: %zu MvFields and %zu RefPicListTabs\n", 
           mv_alloc_size / sizeof(MvField), ref_alloc_size / sizeof(RefPicListTab));

    free(mv_pool);
    free(ref_pool);
}

int main() {
