    // When sb_cols and sb_rows are large, 64 * sb_cols * sb_rows
    // exceeds INT32_MAX and wraps to a negative value.
    // Example: 64 * 65536 * 512 = 2^31 = INT_MIN.
    int sz = 64 * s->sb_cols * s->sb_rows;

    // Line 119: Allocation with corrupted size
    // The allocator receives the negative/wrapped sz.
    // Depending on the implementation, this may allocate a small buffer
    // or fail. The vulnerability relies on the mismatch between
    // expected size and actual allocation.
    void *buffer = malloc(sz);

    if (!buffer) {
        printf("[!] Allocation failed or returned NULL due to negative size.\n");
        return;
    }

    // Line 133: Pointer offset computation using corrupted sz
    // The code computes f->mv using sz. If sz is negative,
    // this pointer points before the allocated buffer region.
    // f->mv = buffer + sz;
    s->mv = buffer + sz;

    // Educational demonstration of the OOB condition
    printf("[+] Buffer allocated at: %p\n", (void*)buffer);
    printf("[+] Calculated sz: %d (0x%x)\n", sz, sz);
    printf("[+] f->mv computed at: %p\n", s->mv);
    printf("[!] f->mv points %ld bytes BEFORE the buffer (Out-of-Bounds)\n",
           (char*)buffer - (char*)s->mv);

    // NOTE: Actual write to s->mv would cause heap corruption.
    // *(int*)s->mv = 0xDEADBEEF; // Destructive, omitted for safety.
}

int main() {
