typedef struct {
    size_t bit_length;
    uint8_t *data;
} BitStream;

void allocate(uint8_t **buf, size_t size) {
    *buf = malloc(size);
}

int main() {
    BitStream current;

    // EXPLOIT MECHANISM:
    // The vulnerability occurs when bit_length approaches SIZE_MAX.
    // The size calculation (bit_length + 7) / 8 is performed using unsigned arithmetic.
    // Adding 7 to a value near SIZE_MAX causes unsigned integer overflow (wrap-around),
    // resulting in a drastically smaller allocation size than the actual data size.
    current.bit_length = SIZE_MAX - 5;

    // Vulnerable size calculation
    size_t alloc_size = (current.bit_length + 7) / 8;

    printf("[*] bit_length: %zu\n", current.bit_length);
    printf("[*] Calculated alloc_size: %zu\n", alloc_size);
    printf("[!] Note: (bit_length + 7) wrapped around due to unsigned overflow,\n");
    printf("[!] producing a tiny allocation instead of the expected ~%zu bytes.\n", current.bit_length / 8);

    // Allocate based on the overflowed size
    allocate(&current.data, alloc_size);

    // Conceptual representation of the subsequent write loop
    // The original code iterates up to bit_length, writing bytes to the undersized buffer
    printf("[!] Subsequent loop attempts to write ~%zu bytes into a %zu-byte buffer.\n",
           current.bit_length / 8, alloc_size);
    printf("[!] This size mismatch triggers a heap buffer overflow.\n");

    free(current.data);
    return 0;
}

